/* Contact only: animation prepares the existing mailto flow; it never claims delivery. */
(()=>{
 const root=document.querySelector('#contact'),form=root.querySelector('#contact-form'),button=form.querySelector('.contact-submit'),message=form.querySelector('#message'),counter=root.querySelector('#message-counter'),scene=root.querySelector('.contact-transmission-scene'),svg=root.querySelector('.transmission-beam'),port=root.querySelector('.satellite-port'),receiver=root.querySelector('.earth-receive-point'),packet=root.querySelector('.contact-data-packet'),status=root.querySelector('#form-status'),reduced=matchMedia('(prefers-reduced-motion:reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');
 const preview=new URLSearchParams(location.search).has('transmission-preview');let visible=false,busy=false,bypass=false,pointerFrame=0,point=null;
 function count(){counter.textContent=`${message.value.length} / 500`}message.addEventListener('input',count);count();
 function path(){const s=scene.getBoundingClientRect(),a=port.getBoundingClientRect(),b=receiver.getBoundingClientRect(),x=a.left+a.width/2-s.left,y=a.top+a.height/2-s.top,ex=b.left+b.width/2-s.left,ey=b.top+b.height/2-s.top;svg.setAttribute('viewBox',`0 0 ${Math.max(s.width,1)} ${Math.max(s.height,1)}`);const d=`M ${x} ${y} C ${x+Math.max(40,s.width*.17)} ${y+s.height*.06}, ${ex-s.width*.15} ${ey-s.height*.13}, ${ex} ${ey}`;svg.querySelectorAll('path').forEach(p=>p.setAttribute('d',d))}new ResizeObserver(path).observe(scene);scene.querySelectorAll('img').forEach(img=>img.addEventListener('load',path));path();
 function visibility(){root.classList.toggle('contact-paused',!visible||document.hidden);if(!visible||document.hidden||reduced.matches)svg.pauseAnimations?.();else svg.unpauseAnimations?.()}new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)root.classList.add('satellite-entered');visibility()},{rootMargin:'30px',threshold:.01}).observe(root);document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',visibility);
 function parallax(){pointerFrame=0;if(!point||reduced.matches||!visible)return;const r=scene.getBoundingClientRect(),x=Math.max(-.5,Math.min(.5,(point.clientX-r.left)/r.width-.5)),y=Math.max(-.5,Math.min(.5,(point.clientY-r.top)/r.height-.5));root.style.setProperty('--sat-x',`${x*5}px`);root.style.setProperty('--sat-y',`${y*4}px`);root.style.setProperty('--earth-x',`${x*2}px`);root.style.setProperty('--earth-y',`${y*2}px`)}if(fine.matches){root.addEventListener('pointermove',e=>{point=e;if(!pointerFrame)pointerFrame=requestAnimationFrame(parallax)},{passive:true});root.addEventListener('pointerleave',()=>{point=null;['--sat-x','--sat-y','--earth-x','--earth-y'].forEach(p=>root.style.removeProperty(p))})}
 const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
 async function prepare(){busy=true;button.disabled=true;button.setAttribute('aria-busy','true');root.classList.add('is-preparing');status.textContent='Préparation du message…';const fields=[...form.querySelectorAll('input,textarea,select')];fields.forEach(f=>{if(f.tagName==='SELECT')f.disabled=true;else f.readOnly=true});let flight;
  try{if(!reduced.matches){const plane=form.querySelector('.send-plane');flight=plane.animate([{transform:'translate(0,0)',opacity:1},{transform:'translate(32px,-22px)',opacity:0}],{duration:350,easing:'ease-in',fill:'forwards'});const r=root.getBoundingClientRect(),a=button.getBoundingClientRect(),b=port.getBoundingClientRect(),sx=a.left+a.width*.25-r.left,sy=a.top+a.height*.5-r.top,ex=b.left+b.width*.5-r.left,ey=b.top+b.height*.5-r.top;await packet.animate([{transform:`translate3d(${sx}px,${sy}px,0)`,opacity:0,offset:0},{transform:`translate3d(${sx-45}px,${sy-30}px,0)`,opacity:1,offset:.15},{transform:`translate3d(${ex}px,${ey}px,0)`,opacity:1,offset:.9},{transform:`translate3d(${ex}px,${ey}px,0)`,opacity:0,offset:1}],{duration:950,easing:'cubic-bezier(.25,.6,.35,1)'}).finished;root.classList.add('is-transmitting');status.textContent='Message préparé. Ouverture de votre messagerie…';await pause(1050)}}catch{status.textContent='Votre message est prêt à être préparé dans votre messagerie.'}
  finally{root.classList.remove('is-transmitting','is-preparing');flight?.cancel();fields.forEach(f=>{f.disabled=false;f.readOnly=false});button.disabled=false;button.removeAttribute('aria-busy');busy=false}
  if(preview){status.textContent='Prévisualisation terminée — aucun message n’a été envoyé.';root.dataset.previewComplete='true';return}bypass=true;try{form.requestSubmit(button)}finally{bypass=false}
 }
 form.addEventListener('submit',e=>{if(bypass)return;if(busy){e.preventDefault();e.stopImmediatePropagation();return}const fields=[...form.querySelectorAll('input,textarea,select')],valid=fields.every(f=>f.value.trim()&&f.checkValidity())&&message.value.trim().length>=10;if(!valid)return;e.preventDefault();e.stopImmediatePropagation();prepare()},true);
})();
